/* validate-then-act, the only STM shape C can support cheaply */
int64_t transfer(account_t *from, account_t *to, int64_t amt) {
    for (;;) {
        int64_t f = atomic_load_explicit(&from->bal, memory_order_acquire);
        int64_t t = atomic_load_explicit(&to->bal,   memory_order_acquire);
        if (f < amt) return -1;
        if (atomic_compare_exchange_strong(&from->bal, &f, f - amt) &&
            atomic_compare_exchange_strong(&to->bal,   &t, t + amt))
            return 0;
        /* on failure the transaction replays: re-read BOTH, recompute BOTH */
    }
}
